        "-    pub async fn execute_resolved_pending_action(",
        "-        &self,",
        "-        action_name: &str,",
        "-        parameters: serde_json::Value,",
        "-        lease: &CapabilityLease,",
        "-        context: &ThreadExecutionContext,",
        "-        approval_already_granted: bool,",
        "-    ) -> Result<ActionResult, EngineError> {",
