        "+            id: lunarwing_engine::types::capability::LeaseId::new(),",
        "+            thread_id: lunarwing_engine::ThreadId::new(),",
        "+            capability_name: "tools".into(),",
        "+            granted_actions: lunarwing_engine::GrantedActions::All,",
        "+            granted_at: chrono::Utc::now(),",
        "+            expires_at: None,",
