    // ── RelayChannelGate ─────────────────────────────────────

    #[tokio::test]
    async fn test_relay_channel_denies_approval_requiring_tools() {
        let gate = RelayChannelGate;
        let ad = action_def("shell", true);
        let auto = HashSet::new();
        let params = serde_json::json!({});
        let c = ctx(
