        assert!(matches!(gate.evaluate(&c).await, GateDecision::Deny { .. }));
    }

    #[tokio::test]
    async fn test_non_relay_channel_always_allows() {
        let gate = RelayChannelGate;
        let ad = action_def("shell", true);
        let auto = HashSet::new();
