        let params = serde_json::json!({});
        let c = ctx(
            &ad,
            ExecutionMode::Interactive,
            "slack-relay",
            &auto,
            &params,
        );
        assert!(matches!(gate.evaluate(&c).await, GateDecision::Allow));
    }
