        "+        "rate_limit"",
        "+    }",
        "+",
        "+    fn priority(&self) -> u32 {",
        "+        50",
        "+    }",
        "+",
        "+    async fn evaluate(&self, ctx: &GateContext<'_>) -> GateDecision {",
        "+        let tool = match self.tools.get(ctx.action_name).await {",
        "+            Some(t) => t,",
        "+            None => return GateDecision::Allow,",
        "+        };",
