        "-            .call_count",
        "-            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);",
        "-        if count >= MAX_CALLS_PER_STEP {",
        "-            return Err(EngineError::Effect {",
        "-                reason: format!(",
        "-                    "Tool call limit reached ({MAX_CALLS_PER_STEP} per code step). \",
        "-                     Break your task into multiple steps."",
