        "-            return Err(EngineError::Effect {",
        "-                reason: format!(",
        "-                    "Tool '{}' is not available in engine v2. \",
        "-                     Tell the user to use the slash command instead (e.g. /routine, /job).",",
        "-                    action_name",
        "-                ),",
        "-            });",
        "-        }",
        "-",
